{"path": "/workspace/main_solve.py", "content": "import hashlib, json, glob, sys

P = (1 << 61) - 1  # Mersenne prime

def gen_pubkey(secret_hex):
    secret = bytes.fromhex(secret_hex)
    state = hashlib.sha256(secret).digest()
    A = []
    for _ in range(128):
        A.append(int.from_bytes(state, "big"))
        state = hashlib.sha256(state).digest()
    return A

def happiness(x):
    return x - sum((x >> i) for i in range(1, x.bit_length()))

def solve_mod(rows, ncols, p=P):
    mat = [r[:] for r in rows]
    pivots = {}
    r = 0
    for col in range(ncols):
        piv = None
        for rr in range(r, len(mat)):
            if mat[rr][col] % p:
                piv = rr
                break
        if piv is None:
            continue
        mat[r], mat[piv] = mat[piv], mat[r]
        inv = pow(mat[r][col] % p, p - 2, p)
        mat[r] = [(v * inv) % p for v in mat[r]]
        for rr in range(len(mat)):
            if rr != r and mat[rr][col] % p:
                f = mat[rr][col] % p
                mat[rr] = [(a - f * b) % p for a, b in zip(mat[rr], mat[r])]
        pivots[col] = r
        r += 1
        if r == len(mat):
            break
    # consistency
    for rr in range(r, len(mat)):
        if all(v % p == 0 for v in mat[rr][:ncols]) and mat[rr][ncols] % p:
            return None, pivots, "inconsistent"
    sol = [0] * ncols
    for col, rr in pivots.items():
        sol[col] = mat[rr][ncols] % p
    return sol, pivots, "ok (rank=%d)" % r

def recover(samples):
    """samples: list of (secret_hex, enc). Returns (flag_bytes, diagnostics)."""
    nblocks = len(samples[0][1])
    assert all(len(e) == nblocks for _, e in samples)
    blocks_out = []
    diag = []
    for k in range(nblocks):
        rows = []
        for secret_hex, enc in samples:
            A = gen_pubkey(secret_hex)
            cvec = enc[k]
            assert len(A) == len(cvec)
            for j in range(len(A)):
                aj = A[j]
                row = [0] * 256
                # bit i of aj
                x = aj
                i = 0
                while x:
                    if x & 1:
                        row[i] = 1
                    x >>= 1
                    i += 1
                row.append(cvec[j])
                rows.append(row)
        sol, pivots, status = solve_mod(rows, 256)
        if sol is None:
            diag.append((k, status))
            blocks_out.append(None)
            continue
        if any(v not in (0, 1) for v in sol):
            diag.append((k, status + " NONBINARY " + repr(sorted(set(sol))[:10])))
            blocks_out.append(None)
            continue
        m = sum(v << i for i, v in enumerate(sol))
        b = m.to_bytes(32, "big")
        # exact verification across all samples
        ok = True
        for secret_hex, enc in samples:
            A = gen_pubkey(secret_hex)
            if [happiness(a & m) for a in A] != enc[k]:
                ok = False
                break
        diag.append((k, status + " verified=" + str(ok) + " bytes=" + repr(b)))
        blocks_out.append(b if ok else None)
    if any(b is None for b in blocks_out):
        return None, diag
    return b"".join(blocks_out), diag

if __name__ == "__main__":
    files = sorted(glob.glob("/workspace/main_samples/sample_*.json"))
    if len(sys.argv) > 1:
        files = files[: int(sys.argv[1])]
    samples = []
    for f in files:
        with open(f) as fh:
            d = json.load(fh)
        samples.append((d["secret"], d["enc"]))
    print("loaded", len(samples), "samples; blocks:", [len(e) for _, e in samples])
    flag, diag = recover(samples)
    for d in diag:
        print(d)
    if flag is not None:
        print("RAW:", repr(flag))
        print("STRIPPED:", repr(flag.rstrip(b"\x00")))
        try:
            print("FLAG:", flag.rstrip(b"\x00").decode())
        except Exception as e:
            print("decode error", e)
    else:
        print("NOT FULLY RECOVERED")
"}

