import random, sys

def happiness(x: int) -> int:
    # EXACT copy from /workspace/source.py
    return x - sum((x >> i) for i in range(1, x.bit_length()))

def popcount(x: int) -> int:
    return bin(x).count("1")

bad = 0
# exhaustive small
for x in range(0, 1 << 17):
    if happiness(x) != popcount(x):
        print("MISMATCH", x, happiness(x), popcount(x)); bad += 1
        if bad > 5: sys.exit(1)
print("exhaustive 0..2^17-1 OK")

random.seed(1234)
for trial in range(20000):
    nbits = random.randint(1, 512)
    x = random.getrandbits(nbits)
    if happiness(x) != popcount(x):
        print("MISMATCH random", x); bad += 1; break
print("random 512-bit trials OK" if bad == 0 else "FAILED")

# edge cases
for x in [0, 1, 2, 3, (1 << 512) - 1, 1 << 255, (1 << 255) | 1]:
    assert happiness(x) == popcount(x), x
print("edge cases OK")

# Also verify the alternating-sum form: happiness(x) == sum_j (-1)^{?} ... i.e. check
# x - sum_{i>=1} floor(x/2^i) == sum of bits, using integer floor identities.
for _ in range(2000):
    x = random.getrandbits(random.randint(0, 300))
    s = 0
    i = 1
    while (x >> i):
        s += x >> i
        i += 1
    assert happiness(x) == x - s == popcount(x)
print("floor-form consistency OK")
