{"path": "/workspace/rev_linear.py", "content": """"Independent assessment (agent 39):
- Is c_j = happiness(A[j] & m) linear in the bits of m?  (yes: c_j = sum_{k: bit k of A[j] set} m_k)
- How many independently-secreted samples are needed to pin a 256-bit block?
Simulate with synthetic data, solve over GF(2) and over Q, measure success vs #samples.
"""
import hashlib, random, itertools, sys

# exact source.py logic
def gen_pubkey(secret: bytes, hasher=hashlib.sha512) -> list:
    def hash(m):
        return hasher(m).digest()
    state = hash(secret)
    pubkey = []
    for _ in range(len(hash(b"0")) * 4):
        pubkey.append(int.from_bytes(state, "big"))
        state = hash(state)
    return pubkey

def happiness(x: int) -> int:
    return x - sum((x >> i) for i in range(1, x.bit_length()))

def encode_message(message: bytes, segment_len: int) -> list:
    message += bytes(segment_len - len(message) % (segment_len))
    encoded = []
    for i in range(0, len(message), segment_len):
        encoded.append(int.from_bytes(message[i:i + segment_len], "big"))
    return encoded

def encrypt(pubkey, message: bytes):
    return [[happiness(i & b) for i in pubkey] for b in encode_message(message, len(pubkey) // 4)]

# ---- GF(2) batch solver: build rows over bits of A[j] masked to 256 bits
def solve_gf2(rows, rhs, nvars):
    """rows: list of int bitmasks (bit k = coefficient of m_k); rhs: ints. Returns solution int or None."""
    basis = {}  # pivot -> (mask, val)
    for mask, val in zip(rows, rhs):
        while mask:
            p = mask.bit_length() - 1
            if p in basis:
                bm, bv = basis[p]
                mask ^= bm; val ^= bv
            else:
                basis[p] = (mask, val)
                break
        else:
            if val:
                return None  # inconsistent (can't happen for valid ciphertexts)
    if len(basis) < nvars:
        return None  # underdetermined
    # back-substitute from lowest pivot upward using reduced echelon-ish approach
    sol = 0
    for p in sorted(basis):
        bm, bv = basis[p]
        # bm may contain lower pivots; solve ascending
        v = bv
        rest = bm & ~(1 << p)
        while rest:
            q = rest.bit_length() - 1
            v ^= (sol >> q) & 1
            rest &= ~(1 << q)
        if v:
            sol |= 1 << p
    return sol

def trial(nsamples, seed, blockbits=256):
    rng = random.Random(seed)
    m = rng.getrandbits(blockbits)
    rows, rhs = [], []
    for s in range(nsamples):
        secret = bytes(rng.getrandbits(8) for _ in range(16))
        A = gen_pubkey(secret, hashlib.sha256)
        assert len(A) == 128 and all(a.bit_length() == 256 for a in A)
        for a in A:
            rows.append(a & ((1 << blockbits) - 1))
            rhs.append(happiness(a & m) & 1)  # mod-2 of exact integer equation
    sol = solve_gf2(rows, rhs, blockbits)
    return sol == m, sol is None

random.seed(7)
for n in (1, 2, 3, 4):
    ok = None
    trials = 300 if n <= 2 else 50
    for t in range(trials):
        good, under = trial(n, 1000 * n + t)
        if ok is None:
            ok = 0
        ok += good
    print(f"samples={n}: GF(2) exact recovery {ok}/{trials}")
"}

